def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    from collections import defaultdict
    pts=defaultdict(list)
    for i in range(H):
        for j in range(W):
            if g[i][j]!=4: pts[g[i][j]].append((i,j))
    out=[r[:] for r in g]
    for col,v in pts.items():
        n=len(v)
        if n<2: continue
        # try all pairs on same diagonal/anti-diagonal
        done=set()
        for a in v:
            for b in v:
                if a>=b: continue
                dr=a[0]-b[0]; dc=a[1]-b[1]
                if abs(dr)==abs(dc) and min(abs(dr),abs(dc))<=max(len(v)//2,1):
                    key=(min(a,b), max(a,b))
                    if key in done: continue
                    step=(dr//abs(dr),dc//abs(dc)) if dr else (0,dc//abs(dc))
                    ok=all(0<=b[0]+k*step[0] and 0<=b[1]+k*step[1] for k in range(1,min(abs(dr),abs(dc))))
                    if ok:
                        for k in range(1,min(abs(dr),abs(dc))+1):
                            out[b[0]+k*step[0]][b[1]+k*step[1]]=col
                        done.add(key)
    return out
